let regulationTerms=null,regulationTermsPromise=null,termRenderGeneration=0,termCategory='전체',termPage=1;
async function renderRuleTerms(q){
 const box=document.querySelector('#terms');if(!box)return;const generation=++termRenderGeneration;
 if(!regulationTerms){box.innerHTML='<p class="muted">내규 용어를 불러오는 중입니다…</p>';try{regulationTermsPromise ||= Promise.all(Array.from({length:16},(_,i)=>fetch('glossary-data-'+i+'.json?v=20261013').then(r=>{if(!r.ok)throw Error('용어 자료를 불러오지 못했습니다.');return r.json()}))).then(parts=>parts.flat().sort((a,b)=>a.term.localeCompare(b.term,'ko')));regulationTerms=await regulationTermsPromise;}catch(error){regulationTermsPromise=null;box.innerHTML='<p class="muted" role="alert">'+esc(error.message)+' 새로고침 후 다시 시도해 주세요.</p>';return;}}
 if(generation!==termRenderGeneration||!box.isConnected)return;
 const query=q.trim().toLocaleLowerCase().replace(/\s/g,'');const matches=regulationTerms.filter(t=>(termCategory==='전체'||t.category===termCategory)&&(!query||(t.term+' '+t.body+' '+t.rule).toLocaleLowerCase().replace(/\s/g,'').includes(query)));
 const pages=Math.max(1,Math.ceil(matches.length/24));termPage=Math.min(termPage,pages);const rules=new Set(regulationTerms.map(t=>t.rule)).size;
 box.innerHTML=`<div class="glossary-context"><p>업무 매뉴얼 AI와 같은 내규 자료 · ${rules}개 규정의 ${regulationTerms.length}개 용어 정의</p><small>수집한 최신 파일의 정의를 발췌했습니다. 같은 용어도 규정에 따라 의미가 다를 수 있어요.</small><a href="https://alio.go.kr/item/itemOrganList.do?apbaId=C0258&reportFormRootNo=21110" target="_blank" rel="noopener">ALIO 내규 원문 ↗</a></div><div class="glossary-filters" role="group" aria-label="용어 분야">${['전체','유동화·주택금융','보증','인사·복무','경영·일반'].map(cat=>`<button type="button" data-term-category="${cat}" aria-pressed="${cat===termCategory}">${cat}</button>`).join('')}<span role="status">${matches.length}개 결과</span></div>${matches.slice((termPage-1)*24,termPage*24).map(t=>`<article class="panel glossary-term"><div class="glossary-term-head"><h2>${esc(t.term)}</h2><small>${esc(t.category)}</small></div><p>${esc(t.body)}</p><div class="glossary-source"><strong>${esc(t.rule)}</strong><span>${esc(t.article)} · 개정 ${esc(t.amended)}</span><a href="${esc(t.file_url)}" target="_blank" rel="noopener">정의 원문 ↗</a></div></article>`).join('')||'<p class="glossary-empty">일치하는 용어가 없습니다. 짧은 단어나 규정명으로 검색해 보세요.</p>'}<div class="glossary-pagination"><button type="button" data-term-page="-1" ${termPage===1?'disabled':''}>이전</button><span>${termPage} / ${pages}</span><button type="button" data-term-page="1" ${termPage===pages?'disabled':''}>다음</button></div>`;
}
document.addEventListener('click',e=>{const category=e.target.closest('[data-term-category]'),page=e.target.closest('[data-term-page]');if(!category&&!page)return;if(category){termCategory=category.dataset.termCategory;termPage=1;}else termPage+=Number(page.dataset.termPage);renderRuleTerms(document.querySelector('#term-search')?.value||'');});
document.addEventListener('input',e=>{if(e.target.id==='term-search')termPage=1;},true);


let recruitmentPreview=null,recruitmentSearchVersion=0;
function recruitmentSearchMarkup(){return `<section class="panel"><h2>기업별 채용 일정 찾기</h2><p class="muted">기업명을 검색하고 공고별 서류·필기·면접 일정을 내 달력에 추가하세요.</p><form id="recruitment-search-form" class="extra-actions"><input class="field" name="company" minlength="2" maxlength="80" placeholder="예: 산업은행" aria-label="기업명" required><button class="primary">일정 검색</button></form><p id="recruitment-status" role="status" aria-live="polite"></p><div id="recruitment-results"></div></section>`;}
document.addEventListener('submit',async e=>{
 if(e.target.id!=='recruitment-search-form')return;
 e.preventDefault();const form=e.target,version=++recruitmentSearchVersion,button=form.querySelector('button'),box=document.querySelector('#recruitment-results'),status=document.querySelector('#recruitment-status');
 recruitmentPreview=null;box.replaceChildren();button.disabled=true;status.textContent='공고와 주요 일정을 검색하고 있어요…';
 try{
  const data=await api('/api/jobs/search',{company:String(new FormData(form).get('company')||'').trim()});
  if(!form.isConnected||version!==recruitmentSearchVersion)return;
  recruitmentPreview=data;status.textContent=data.postings.length?data.notice:'출처에서 확인할 수 있는 현재 채용 일정을 찾지 못했습니다. 위 공고 사이트에서 기업명으로 확인해 주세요.';
  box.innerHTML=data.postings.map(p=>`<article class="panel"><h3>${esc(p.title)}</h3><a class="auth-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">공고 출처 확인 ↗</a><div class="recruitment-stages">${p.stages.map(s=>`<label class="recruitment-stage"><input type="checkbox" data-recruitment-id="${esc(s.id)}" ${s.day?'':'disabled'}><span><strong>${esc(s.label)}</strong><br><time>${s.day?esc(s.day)+(s.end_day&&s.end_day!==s.day?' ~ '+esc(s.end_day):''):'일정 미발표'}</time> <small>${s.status==='tentative'?'예정 · 변경 가능':s.day?'공고 기재 일정':''}</small>${s.note?`<br><small>${esc(s.note)}</small>`:''}</span></label>`).join('')}</div></article>`).join('')+(data.postings.length?'<button type="button" class="primary" id="recruitment-import">선택한 일정 내 달력에 추가</button><p class="muted">기간 일정은 시작일과 종료일로 추가됩니다. 추가 후 달력에서 삭제할 수 있어요. 공고 변경은 자동 반영되지 않습니다.</p>':'');
 }catch(error){if(form.isConnected)status.textContent=error.message;}
 finally{if(form.isConnected)button.disabled=false;}
});
document.addEventListener('click',async e=>{
 const button=e.target.closest('#recruitment-import');if(!button||!recruitmentPreview)return;
 const status=document.querySelector('#recruitment-status'),ids=[...document.querySelectorAll('[data-recruitment-id]:checked')].map(x=>x.dataset.recruitmentId);
 if(!ids.length){status.textContent='달력에 추가할 일정을 먼저 선택해 주세요.';return;}
 button.disabled=true;
 try{
  const data=await api('/api/jobs/import',{token:recruitmentPreview.token,ids});
  await loadActivity();
  if(status.isConnected)status.textContent=`${data.added}개 일정을 내 달력에 추가했습니다.${data.skipped?' 이미 등록된 '+data.skipped+'개는 건너뛰었습니다.':''} 대시보드 달력에서 확인하세요.`;
 }catch(error){if(status.isConnected)status.textContent=error.message;}
 finally{if(button.isConnected)button.disabled=false;}
});


